package com.pridesys.ticketing.users.service;
import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import com.pridesys.ticketing.repository.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProjectService {private final ProjectRepository projects;private final ModuleRepository modules;private final ProjectMembershipRepository memberships;public ProjectService(ProjectRepository p,ModuleRepository m,ProjectMembershipRepository mm){projects=p;modules=m;memberships=mm;}public List<ProjectRecord> projects(UserEntity a){return (a.getRole()==UserRole.APP_ADMIN?projects.findAll():projects.forUser(a.getId())).stream().map(this::project).toList();}public ProjectRecord create(UserEntity a,UsersProjectsDtos.CreateProjectRequest r){admin(a);return project(projects.save(new ProjectEntity(r.name().trim(),r.shortCode().trim().toUpperCase(),r.description())));}public void update(UserEntity a,long id,UsersProjectsDtos.UpdateProjectRequest r){admin(a);var p=projects.findById(id).orElseThrow();p.setName(r.name().trim());p.setDescription(r.description());if(r.active()!=null)p.setActive(r.active());projects.save(p);}public void member(UserEntity a,long p,long u,boolean add){admin(a);var id=new ProjectMembershipId(p,u);if(add)memberships.save(new ProjectMembershipEntity(p,u));else memberships.deleteById(id);}public List<ModuleRecord> modules(UserEntity a,long p){scope(a,p);return modules.findByProjectIdOrderByName(p).stream().map(this::module).toList();}public ModuleRecord createModule(UserEntity a,long p,UsersProjectsDtos.CreateModuleRequest r){scope(a,p);return module(modules.save(new ModuleEntity(p,r.name().trim(),r.description())));}public void updateModule(UserEntity a,long p,long id,UsersProjectsDtos.UpdateModuleRequest r){scope(a,p);var m=modules.findById(id).orElseThrow();m.setName(r.name().trim());m.setDescription(r.description());if(r.active()!=null)m.setActive(r.active());modules.save(m);}public void deleteModule(UserEntity a,long p,long id){scope(a,p);modules.deleteById(id);}private void scope(UserEntity a,long p){if(a.getRole()!=UserRole.APP_ADMIN&&!projects.member(p,a.getId()))throw new AccessDeniedException("Project access denied");}private void admin(UserEntity a){if(a.getRole()!=UserRole.APP_ADMIN)throw new AccessDeniedException("APP_ADMIN required");}private ProjectRecord project(ProjectEntity p){return new ProjectRecord(p.getId(),p.getName(),p.getShortCode(),p.getDescription(),p.isActive());}private ModuleRecord module(ModuleEntity m){return new ModuleRecord(m.getId(),m.getProjectId(),m.getName(),m.getDescription(),m.isActive());}}
